public interface IBoundedPipeline<TIn, TOut>
{
    Task<IReadOnlyList<TOut>> ProcessAsync(IReadOnlyList<TIn> input, CancellationToken ct);
}

public sealed class BoundedPipeline<TIn, TOut> : IBoundedPipeline<TIn, TOut>
{
    private readonly Func<TIn, CancellationToken, Task<TOut>> _worker;
    private readonly int _maxParallel;

    public BoundedPipeline(Func<TIn, CancellationToken, Task<TOut>> worker, int maxParallel)
    {
        _worker = worker;
        _maxParallel = maxParallel;
    }

    public async Task<IReadOnlyList<TOut>> ProcessAsync(IReadOnlyList<TIn> input, CancellationToken ct)
    {
        var results = new TOut[input.Count];
        using var gate = new SemaphoreSlim(_maxParallel, _maxParallel);
        var tasks = new Task[input.Count];
        for (var i = 0; i < input.Count; i++)
        {
            var index = i;
            tasks[i] = RunIndexAsync(index, input[index], results, gate, ct);
        }
        await Task.WhenAll(tasks).ConfigureAwait(false);
        return results;
    }

    private async Task RunIndexAsync(int index, TIn item, TOut[] results, SemaphoreSlim gate, CancellationToken ct)
    {
        await gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            results[index] = await _worker(item, ct).ConfigureAwait(false);
        }
        finally { gate.Release(); }
    }
}
